def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    color_by_inner_size = {3: 8, 5: 4, 7: 3}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                x, y = stack.pop()
                comp.add((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            r0 = min(x for x, _ in comp)
            r1 = max(x for x, _ in comp)
            c0 = min(y for _, y in comp)
            c1 = max(y for _, y in comp)

            inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
            if inner_h != inner_w or inner_h not in color_by_inner_size:
                continue

            border = (
                {(r0, y) for y in range(c0, c1 + 1)}
                | {(r1, y) for y in range(c0, c1 + 1)}
                | {(x, c0) for x in range(r0, r1 + 1)}
                | {(x, c1) for x in range(r0, r1 + 1)}
            )
            if not border <= comp:
                continue

            fill = color_by_inner_size[inner_h]
            for x in range(r0 + 1, r1):
                for y in range(c0 + 1, c1):
                    if grid[x][y] == 0:
                        out[x][y] = fill

    return out
